-- Przemysław Wencel: czas realizacji, gwarancja, Dworek (stalowa rama, stałe posadowienie), teksty.
BEGIN;
UPDATE product SET description = 'Domek w formie stodoły na stalowej ramie: 40 m² podstawy i 20 m² antresoli, razem 60 m² powierzchni użytkowej. Na parterze jest część wypoczynkowa z aneksem kuchennym, łazienka i sypialnia, na piętrze druga sypialnia. Ściany i dach mają grubość 25 cm. Wizualizacje pokazują trzy warianty elewacji: drewnianą boazerię, blachę CORTEN i ciemną blachę na rąbek. Dom można wielokrotnie przenosić. Cena obejmuje instalację elektryczną i hydrauliczną wykonaną zgodnie z obowiązującymi normami, bez umeblowania i sprzętu. Układ pomieszczeń ustala klient.', construction_system = 'Stalowa rama nośna z wypełnieniem ścian w technologii szkieletowej: drewno konstrukcyjne C-24, izolacja do wyboru (piana PUR, wełna mineralna lub włókno drzewne), grubość ściany i dachu 25 cm. Podłoga: płyta OSB z panelem winylowym.', customization_scope = 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje. Elewację, izolację, wykończenie wnętrza i ogrzewanie wybiera się w opcjach dodatkowych (cena bazowa zakłada podstawowe warianty, dopłaty są podane przy opcjach).', foundation_status = 'temporary', technical_specs = '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Do wyboru: maty na podczerwień w podłodze, klimatyzacja grzewczo-chłodząca lub piec na pelet.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, production_lead_time_weeks_min = 4, production_lead_time_weeks_max = 4, structural_warranty_years = 2, updated_at = now() WHERE id = '2a347d43-accb-516a-a066-494b4982b81c';
UPDATE product SET description = 'Domek na stalowej ramie złożony z dwóch modułów po 34 m², połączonych zadaszonym łącznikiem o powierzchni 7 m², z tarasem 15 m² (razem 90 m²). Jedna część to strefa wypoczynkowa z aneksem kuchennym i łazienką, druga to salon z sypialnią. Dom można wielokrotnie przenosić. Cena obejmuje instalację elektryczną i hydrauliczną wykonaną zgodnie z obowiązującymi normami, bez umeblowania i sprzętu. Układ pomieszczeń ustala klient.', construction_system = 'Stalowa rama nośna z wypełnieniem ścian w technologii szkieletowej: drewno konstrukcyjne C-24 o przekroju 200x60 mm, izolacja do wyboru (piana PUR, wełna mineralna lub włókno drzewne). Podłoga: płyta OSB z panelem winylowym.', customization_scope = 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje. Elewację, izolację, wykończenie wnętrza i ogrzewanie wybiera się w opcjach dodatkowych (cena bazowa zakłada podstawowe warianty, dopłaty są podane przy opcjach).', foundation_status = 'temporary', technical_specs = '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Do wyboru: maty na podczerwień w podłodze, klimatyzacja grzewczo-chłodząca lub piec na pelet.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, production_lead_time_weeks_min = 4, production_lead_time_weeks_max = 4, structural_warranty_years = 2, updated_at = now() WHERE id = '06b1bfca-362f-5f5c-a7d2-b7804d139167';
UPDATE product SET description = 'Parterowy dom o powierzchni 65 m² w formie dworku, z frontonem i kolumnami przy wejściu. Wysokość ściany w szczycie wynosi około 4 m, a ściany bocznej około 3 m. W domu są salon z aneksem kuchennym, łazienka i sypialnia. Ściany ocieplono 20 cm wełny mineralnej, wszystkie szyby w oknach i drzwiach to bezpieczne szkło VSG, a drzwi wejściowe są antywłamaniowe i przystosowane dla osób niepełnosprawnych. W cenie jest klimatyzacja GREE z funkcją chłodzenia i grzania oraz rekuperator ścienny. Dom stoi na stalowej ramie na stałym posadowieniu, producent nie zaleca jego przestawiania. Cena nie obejmuje wyposażenia i sprzętu.', construction_system = 'Stalowa rama, ściany ocieplone 20 cm wełny mineralnej. Podłoga: blacha trapezowa (myszownica), 20 cm wełny, płyta OSB 22 mm, wykończenie panelem winylowym lub wykładziną. Dach pokryty blachodachówką.', customization_scope = 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje.', foundation_status = 'permanent', technical_specs = '{"heatSource":"inne","insulation":"Wełna mineralna 20 cm.","ventilation":"rekuperacja","wallBuildUp":"Ściany ocieplone 20 cm wełny mineralnej.","windowClass":"Szyby VSG (bezpieczne) we wszystkich oknach i drzwiach.","heatSourceOther":"Klimatyzacja GREE z funkcją grzania i chłodzenia.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, production_lead_time_weeks_min = 4, production_lead_time_weeks_max = 4, structural_warranty_years = 2, updated_at = now() WHERE id = '2010baf0-56d3-5c16-a7a1-ff953e825d8b';
UPDATE product SET description = 'Domek na stalowej ramie o wymiarach 10 x 3,5 m (35 m²) z zadaszonym wejściem, przeznaczony dla 4 osób. Składa się z trzech pomieszczeń: części wypoczynkowo-sypialnianej z aneksem kuchennym, sypialni i łazienki. Dom można z łatwością wielokrotnie przestawiać. Cena obejmuje instalację elektryczną i hydrauliczną wykonaną zgodnie z obowiązującymi normami, bez wyposażenia i sprzętu. Układ pomieszczeń ustala klient.', construction_system = 'Stalowa rama nośna z wypełnieniem ścian w technologii szkieletowej: drewno konstrukcyjne C-24 o przekroju 200x60 mm, izolacja do wyboru (piana PUR, wełna mineralna lub włókno drzewne). Podłoga: płyta OSB z panelem winylowym.', customization_scope = 'Ostateczny układ pomieszczeń ustala klient, producent jest otwarty na jego propozycje. Elewację, izolację, wykończenie wnętrza i ogrzewanie wybiera się w opcjach dodatkowych (cena bazowa zakłada podstawowe warianty, dopłaty są podane przy opcjach).', foundation_status = 'temporary', technical_specs = '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Do wyboru: maty na podczerwień w podłodze, klimatyzacja grzewczo-chłodząca lub piec na pelet.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, production_lead_time_weeks_min = 4, production_lead_time_weeks_max = 4, structural_warranty_years = 2, updated_at = now() WHERE id = '73177ca4-92dc-5f7e-ac02-c8812116bba0';
UPDATE product_translation SET description = 'A barn-style cabin on a steel frame: 40 m² footprint plus a 20 m² mezzanine, 60 m² of usable area in total. The ground floor has a leisure area with a kitchenette, a bathroom and a bedroom, and the upper floor a second bedroom. Walls and roof are 25 cm thick. The visualisations show three facade variants: timber cladding, CORTEN steel and dark standing-seam sheet metal. The house can be moved many times. The price includes electrical and plumbing installations made to current standards, without furniture and appliances. The client decides the room layout.', construction_system = 'Load-bearing steel frame with timber-frame walls: C-24 structural timber, insulation of choice (PUR foam, mineral wool or wood fibre), wall and roof thickness 25 cm. Floor: OSB board with vinyl panels.', customization_scope = 'The client decides the final room layout, and the producer is open to the client''s proposals. Facade, insulation, interior finish and heating are chosen in the additional options (the base price assumes the basic variants, surcharges are shown on each option).', updated_at = now() WHERE product_id = '2a347d43-accb-516a-a066-494b4982b81c' AND locale = 'en';
UPDATE product_translation SET description = 'Ein Haus in Scheunenform auf Stahlrahmen: 40 m² Grundfläche plus 20 m² Galerie, insgesamt 60 m² Nutzfläche. Im Erdgeschoss befinden sich ein Aufenthaltsbereich mit Küchenzeile, ein Bad und ein Schlafzimmer, im Obergeschoss ein zweites Schlafzimmer. Wände und Dach sind 25 cm dick. Die Visualisierungen zeigen drei Fassadenvarianten: Holzverkleidung, CORTEN-Stahl und dunkles Stehfalzblech. Das Haus lässt sich mehrfach versetzen. Der Preis umfasst Elektro- und Sanitärinstallation nach geltenden Normen, ohne Möbel und Geräte. Die Raumaufteilung bestimmt der Kunde.', construction_system = 'Tragender Stahlrahmen mit Wänden in Holzrahmenbauweise: Konstruktionsholz C-24, Dämmung nach Wahl (PUR-Schaum, Mineralwolle oder Holzfaser), Wand- und Dachstärke 25 cm. Boden: OSB-Platte mit Vinylpaneelen.', customization_scope = 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen. Fassade, Dämmung, Innenausbau und Heizung werden in den Zusatzoptionen gewählt (der Basispreis geht von den Standardvarianten aus, Aufpreise stehen bei den Optionen).', updated_at = now() WHERE product_id = '2a347d43-accb-516a-a066-494b4982b81c' AND locale = 'de';
UPDATE product_translation SET description = 'Een huisje in de vorm van een schuur op een stalen frame: 40 m² grondoppervlak plus 20 m² vide, samen 60 m² bruikbare oppervlakte. Op de begane grond bevinden zich een verblijfsruimte met keukenhoek, een badkamer en een slaapkamer, op de verdieping een tweede slaapkamer. Wanden en dak zijn 25 cm dik. De visualisaties tonen drie gevelvarianten: houten bekleding, CORTEN-staal en donkere liggende felsplaat. Het huis kan meerdere keren worden verplaatst. De prijs omvat de elektrische en sanitaire installatie volgens de geldende normen, zonder meubels en apparatuur. De klant bepaalt de indeling.', construction_system = 'Dragend stalen frame met houtskeletwanden: constructiehout C-24, isolatie naar keuze (PUR-schuim, minerale wol of houtvezel), wand- en dakdikte 25 cm. Vloer: OSB-plaat met vinylpanelen.', customization_scope = 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen. Gevel, isolatie, interieurafwerking en verwarming kies je in de aanvullende opties (de basisprijs gaat uit van de standaardvarianten, toeslagen staan bij de opties).', updated_at = now() WHERE product_id = '2a347d43-accb-516a-a066-494b4982b81c' AND locale = 'nl';
UPDATE product_translation SET description = 'Een huisje op een stalen frame, opgebouwd uit twee modules van 34 m², verbonden door een overdekte verbinding van 7 m², met een terras van 15 m² (samen 90 m²). Het ene deel is een verblijfsruimte met keukenhoek en badkamer, het andere een woonkamer met slaapkamer. Het huis kan meerdere keren worden verplaatst. De prijs omvat de elektrische en sanitaire installatie volgens de geldende normen, zonder meubels en apparatuur. De klant bepaalt de indeling.', construction_system = 'Dragend stalen frame met houtskeletwanden: constructiehout C-24, doorsnede 200x60 mm, isolatie naar keuze (PUR-schuim, minerale wol of houtvezel). Vloer: OSB-plaat met vinylpanelen.', customization_scope = 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen. Gevel, isolatie, interieurafwerking en verwarming kies je in de aanvullende opties (de basisprijs gaat uit van de standaardvarianten, toeslagen staan bij de opties).', updated_at = now() WHERE product_id = '06b1bfca-362f-5f5c-a7d2-b7804d139167' AND locale = 'nl';
UPDATE product_translation SET description = 'A cabin on a steel frame made of two 34 m² modules joined by a covered 7 m² connector, with a 15 m² terrace (90 m² in total). One part is a leisure area with a kitchenette and bathroom, the other a living room with a bedroom. The house can be moved many times. The price includes electrical and plumbing installations made to current standards, without furniture and appliances. The client decides the room layout.', construction_system = 'Load-bearing steel frame with timber-frame walls: C-24 structural timber, 200x60 mm section, insulation of choice (PUR foam, mineral wool or wood fibre). Floor: OSB board with vinyl panels.', customization_scope = 'The client decides the final room layout, and the producer is open to the client''s proposals. Facade, insulation, interior finish and heating are chosen in the additional options (the base price assumes the basic variants, surcharges are shown on each option).', updated_at = now() WHERE product_id = '06b1bfca-362f-5f5c-a7d2-b7804d139167' AND locale = 'en';
UPDATE product_translation SET description = 'Ein Haus auf Stahlrahmen aus zwei Modulen von je 34 m², verbunden durch einen überdachten Verbinder von 7 m², mit einer 15 m² großen Terrasse (insgesamt 90 m²). Ein Teil ist der Aufenthaltsbereich mit Küchenzeile und Bad, der andere ein Wohnzimmer mit Schlafzimmer. Das Haus lässt sich mehrfach versetzen. Der Preis umfasst Elektro- und Sanitärinstallation nach geltenden Normen, ohne Möbel und Geräte. Die Raumaufteilung bestimmt der Kunde.', construction_system = 'Tragender Stahlrahmen mit Wänden in Holzrahmenbauweise: Konstruktionsholz C-24, Querschnitt 200x60 mm, Dämmung nach Wahl (PUR-Schaum, Mineralwolle oder Holzfaser). Boden: OSB-Platte mit Vinylpaneelen.', customization_scope = 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen. Fassade, Dämmung, Innenausbau und Heizung werden in den Zusatzoptionen gewählt (der Basispreis geht von den Standardvarianten aus, Aufpreise stehen bei den Optionen).', updated_at = now() WHERE product_id = '06b1bfca-362f-5f5c-a7d2-b7804d139167' AND locale = 'de';
UPDATE product_translation SET description = 'A single-storey 65 m² house in the form of a manor, with a pediment and columns at the entrance. The wall height at the gable is about 4 m and at the side wall about 3 m. The house has a living room with a kitchenette, a bathroom and a bedroom. Walls are insulated with 20 cm of mineral wool, all window and door glazing is safe VSG glass, and the entrance door is burglar-resistant and adapted for people with disabilities. The price includes GREE air conditioning with cooling and heating and a wall-mounted heat recovery unit. The house stands on a steel frame with a permanent foundation, and the producer advises against moving it. The price does not include furnishings and appliances.', construction_system = 'Steel frame, walls insulated with 20 cm of mineral wool. Floor: trapezoidal sheet (checker plate), 20 cm of wool, 22 mm OSB board, finished with vinyl panels or carpet. Roof covered with metal roof tiles.', customization_scope = 'The client decides the final room layout, and the producer is open to the client''s proposals.', updated_at = now() WHERE product_id = '2010baf0-56d3-5c16-a7a1-ff953e825d8b' AND locale = 'en';
UPDATE product_translation SET description = 'Ein eingeschossiges Haus mit 65 m² in Form eines Gutshauses, mit Giebel und Säulen am Eingang. Die Wandhöhe am Giebel beträgt etwa 4 m, an der Seitenwand etwa 3 m. Im Haus befinden sich ein Wohnraum mit Küchenzeile, ein Bad und ein Schlafzimmer. Die Wände sind mit 20 cm Mineralwolle gedämmt, alle Scheiben in Fenstern und Türen sind sicheres VSG-Glas, und die Eingangstür ist einbruchhemmend und behindertengerecht. Im Preis enthalten sind eine GREE-Klimaanlage mit Kühl- und Heizfunktion sowie ein Wandlüftungsgerät mit Wärmerückgewinnung. Das Haus steht auf einem Stahlrahmen mit festem Fundament, der Hersteller rät vom Versetzen ab. Der Preis enthält keine Ausstattung und Geräte.', construction_system = 'Stahlrahmen, Wände mit 20 cm Mineralwolle gedämmt. Boden: Trapezblech (Riffelblech), 20 cm Wolle, OSB-Platte 22 mm, Abschluss mit Vinylpaneelen oder Teppichboden. Dach mit Blechdachziegeln gedeckt.', customization_scope = 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen.', updated_at = now() WHERE product_id = '2010baf0-56d3-5c16-a7a1-ff953e825d8b' AND locale = 'de';
UPDATE product_translation SET description = 'Een gelijkvloerse woning van 65 m² in de vorm van een landhuis, met fronton en kolommen bij de ingang. De wandhoogte bij de gevelpunt bedraagt ongeveer 4 m en bij de zijwand ongeveer 3 m. In het huis zijn een woonkamer met keukenhoek, een badkamer en een slaapkamer. De wanden zijn geïsoleerd met 20 cm minerale wol, alle beglazing in ramen en deuren is veilig VSG-glas en de voordeur is inbraakwerend en aangepast voor mensen met een beperking. In de prijs zijn een GREE-airconditioning met koel- en verwarmfunctie en een wandventilatie-unit met warmteterugwinning inbegrepen. Het huis staat op een stalen frame met een vaste fundering en de producent raadt af het te verplaatsen. De prijs omvat geen inrichting en apparatuur.', construction_system = 'Stalen frame, wanden geïsoleerd met 20 cm minerale wol. Vloer: trapeziumplaat (strekmetaal), 20 cm wol, OSB-plaat 22 mm, afgewerkt met vinylpanelen of tapijt. Dak bedekt met metalen dakpannen.', customization_scope = 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen.', updated_at = now() WHERE product_id = '2010baf0-56d3-5c16-a7a1-ff953e825d8b' AND locale = 'nl';
UPDATE product_translation SET description = 'A cabin on a steel frame measuring 10 x 3.5 m (35 m²) with a covered entrance, designed for 4 people. It has three rooms: a living and sleeping area with a kitchenette, a bedroom and a bathroom. The house can easily be moved many times. The price includes electrical and plumbing installations made to current standards, without furnishings and appliances. The client decides the room layout.', construction_system = 'Load-bearing steel frame with timber-frame walls: C-24 structural timber, 200x60 mm section, insulation of choice (PUR foam, mineral wool or wood fibre). Floor: OSB board with vinyl panels.', customization_scope = 'The client decides the final room layout, and the producer is open to the client''s proposals. Facade, insulation, interior finish and heating are chosen in the additional options (the base price assumes the basic variants, surcharges are shown on each option).', updated_at = now() WHERE product_id = '73177ca4-92dc-5f7e-ac02-c8812116bba0' AND locale = 'en';
UPDATE product_translation SET description = 'Ein Haus auf Stahlrahmen mit den Maßen 10 x 3,5 m (35 m²) und überdachtem Eingang, ausgelegt für 4 Personen. Es besteht aus drei Räumen: einem Wohn- und Schlafbereich mit Küchenzeile, einem Schlafzimmer und einem Bad. Das Haus lässt sich problemlos mehrfach versetzen. Der Preis umfasst Elektro- und Sanitärinstallation nach geltenden Normen, ohne Ausstattung und Geräte. Die Raumaufteilung bestimmt der Kunde.', construction_system = 'Tragender Stahlrahmen mit Wänden in Holzrahmenbauweise: Konstruktionsholz C-24, Querschnitt 200x60 mm, Dämmung nach Wahl (PUR-Schaum, Mineralwolle oder Holzfaser). Boden: OSB-Platte mit Vinylpaneelen.', customization_scope = 'Die endgültige Raumaufteilung bestimmt der Kunde, der Hersteller ist für dessen Vorschläge offen. Fassade, Dämmung, Innenausbau und Heizung werden in den Zusatzoptionen gewählt (der Basispreis geht von den Standardvarianten aus, Aufpreise stehen bei den Optionen).', updated_at = now() WHERE product_id = '73177ca4-92dc-5f7e-ac02-c8812116bba0' AND locale = 'de';
UPDATE product_translation SET description = 'Een huisje op een stalen frame van 10 x 3,5 m (35 m²) met overdekte ingang, bedoeld voor 4 personen. Het bestaat uit drie ruimtes: een woon- en slaapgedeelte met keukenhoek, een slaapkamer en een badkamer. Het huis kan gemakkelijk meerdere keren worden verplaatst. De prijs omvat de elektrische en sanitaire installatie volgens de geldende normen, zonder inrichting en apparatuur. De klant bepaalt de indeling.', construction_system = 'Dragend stalen frame met houtskeletwanden: constructiehout C-24, doorsnede 200x60 mm, isolatie naar keuze (PUR-schuim, minerale wol of houtvezel). Vloer: OSB-plaat met vinylpanelen.', customization_scope = 'De klant bepaalt de uiteindelijke indeling en de producent staat open voor zijn voorstellen. Gevel, isolatie, interieurafwerking en verwarming kies je in de aanvullende opties (de basisprijs gaat uit van de standaardvarianten, toeslagen staan bij de opties).', updated_at = now() WHERE product_id = '73177ca4-92dc-5f7e-ac02-c8812116bba0' AND locale = 'nl';
COMMIT;
